import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// ---------------------------------------------------------------------------
// Stage — shared three.js viewport for every 3D rig: renderer, orbit camera
// (drag + auto-rotate), warm sun + soft shadows, a textured grass ground, and
// a library of PROCEDURAL canvas textures (wood, metal, asphalt, foliage,
// fabric, concrete, grass, plastic) that are UV-mapped with RepeatWrapping and
// paired bump maps for surface relief. No external image assets required.
// ---------------------------------------------------------------------------

export type TexName =
  | 'wood'
  | 'metal'
  | 'asphalt'
  | 'leaf'
  | 'fabric'
  | 'concrete'
  | 'grass'
  | 'plastic';

// ---- colour helpers ----
function toRGB(hex: number): [number, number, number] {
  return [(hex >> 16) & 255, (hex >> 8) & 255, hex & 255];
}
function cl(v: number) {
  return Math.max(0, Math.min(255, v | 0));
}
function shade(hex: number, amt: number, sat = 1) {
  const [r, g, b] = toRGB(hex);
  return `rgb(${cl(r + amt)},${cl(g + amt * sat)},${cl(b + amt)})`;
}

// ---- procedural texture drawing (returns an HTMLCanvasElement) ----
function drawTexture(name: TexName, color: number, S = 128): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = c.height = S;
  const x = c.getContext('2d')!;
  const [r, g, b] = toRGB(color);
  x.fillStyle = `rgb(${r},${g},${b})`;
  x.fillRect(0, 0, S, S);
  const rnd = (a: number, bb: number) => a + Math.random() * (bb - a);

  if (name === 'wood') {
    for (let i = 0; i < 90; i++) {
      x.strokeStyle = shade(color, rnd(-26, 14));
      x.lineWidth = rnd(0.5, 1.6);
      const y = rnd(0, S);
      x.beginPath();
      x.moveTo(0, y);
      for (let px = 0; px <= S; px += 8) x.lineTo(px, y + Math.sin(px * 0.08 + i) * 1.5);
      x.stroke();
    }
    for (let p = 0; p <= S; p += S / 4) {
      x.strokeStyle = shade(color, -34);
      x.lineWidth = 1.5;
      x.beginPath();
      x.moveTo(0, p);
      x.lineTo(S, p);
      x.stroke();
    }
    for (let k = 0; k < 3; k++) {
      x.strokeStyle = shade(color, -30);
      x.beginPath();
      x.ellipse(rnd(0, S), rnd(0, S), rnd(2, 5), rnd(3, 7), 0, 0, Math.PI * 2);
      x.stroke();
    }
  } else if (name === 'metal') {
    for (let i = 0; i < 160; i++) {
      x.strokeStyle = shade(color, rnd(-22, 30));
      x.lineWidth = rnd(0.4, 1);
      const y = rnd(0, S);
      x.beginPath();
      x.moveTo(0, y);
      x.lineTo(S, y);
      x.stroke();
    }
  } else if (name === 'asphalt') {
    for (let i = 0; i < 2600; i++) {
      x.fillStyle = shade(color, rnd(-34, 34));
      const s = rnd(0.6, 2.2);
      x.fillRect(rnd(0, S), rnd(0, S), s, s);
    }
  } else if (name === 'leaf') {
    for (let i = 0; i < 320; i++) {
      x.fillStyle = shade(color, rnd(-40, 34), 1.3);
      x.beginPath();
      x.arc(rnd(0, S), rnd(0, S), rnd(2.5, 7), 0, Math.PI * 2);
      x.fill();
    }
  } else if (name === 'fabric') {
    for (let p = 0; p < S; p += 3) {
      x.strokeStyle = shade(color, 12);
      x.globalAlpha = 0.35;
      x.beginPath();
      x.moveTo(p, 0);
      x.lineTo(p, S);
      x.stroke();
      x.strokeStyle = shade(color, -16);
      x.beginPath();
      x.moveTo(0, p);
      x.lineTo(S, p);
      x.stroke();
    }
    x.globalAlpha = 1;
  } else if (name === 'concrete') {
    for (let i = 0; i < 1800; i++) {
      x.fillStyle = shade(color, rnd(-18, 22));
      x.fillRect(rnd(0, S), rnd(0, S), 1, 1);
    }
  } else if (name === 'grass') {
    for (let i = 0; i < 2200; i++) {
      x.strokeStyle = shade(color, rnd(-30, 26), 1.4);
      x.lineWidth = 1;
      const gx = rnd(0, S);
      const gy = rnd(0, S);
      x.beginPath();
      x.moveTo(gx, gy);
      x.lineTo(gx + rnd(-1.5, 1.5), gy - rnd(2, 5));
      x.stroke();
    }
  } else if (name === 'plastic') {
    const grad = x.createLinearGradient(0, 0, 0, S);
    grad.addColorStop(0, shade(color, 30));
    grad.addColorStop(0.5, shade(color, 4));
    grad.addColorStop(1, shade(color, -22));
    x.fillStyle = grad;
    x.fillRect(0, 0, S, S);
    for (let i = 0; i < 400; i++) {
      x.fillStyle = shade(color, rnd(-8, 8));
      x.fillRect(rnd(0, S), rnd(0, S), 1, 1);
    }
  }
  return c;
}

const _texCache = new Map<string, THREE.CanvasTexture>();
function getTex(three: typeof THREE, name: TexName, color: number, rx: number, ry: number) {
  const key = `${name}:${color}:${rx}:${ry}`;
  const hit = _texCache.get(key);
  if (hit) return hit;
  const tex = new three.CanvasTexture(drawTexture(name, color));
  tex.wrapS = tex.wrapT = three.RepeatWrapping;
  tex.repeat.set(rx, ry);
  tex.anisotropy = 4;
  (tex as unknown as { colorSpace: string }).colorSpace = (three as unknown as { SRGBColorSpace: string }).SRGBColorSpace;
  _texCache.set(key, tex);
  return tex;
}

// ---- material + geometry helpers ----
export interface MatOpts {
  rough?: number;
  metal?: number;
  flat?: boolean;
  emissive?: number;
  opacity?: number;
  tex?: TexName;
  repeat?: [number, number];
  bump?: number;
}
export function mat(three: typeof THREE, color: number, o: MatOpts = {}) {
  const m = new three.MeshStandardMaterial({
    color: o.tex ? 0xffffff : color,
    roughness: o.rough ?? 0.82,
    metalness: o.metal ?? 0.0,
    flatShading: o.flat ?? false,
    emissive: o.emissive ?? 0x000000,
    transparent: o.opacity != null,
    opacity: o.opacity ?? 1,
  });
  if (o.tex) {
    const [rx, ry] = o.repeat ?? [1, 1];
    const t = getTex(three, o.tex, color, rx, ry);
    m.map = t;
    m.bumpMap = t;
    m.bumpScale = o.bump ?? 0.02;
  }
  return m;
}
export function box(
  three: typeof THREE,
  dims: [number, number, number],
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts & { rotX?: number; rotY?: number; rotZ?: number } = {},
) {
  const m = new three.Mesh(new three.BoxGeometry(...dims), mat(three, color, o));
  m.position.set(...pos);
  if (o.rotX) m.rotation.x = o.rotX;
  if (o.rotY) m.rotation.y = o.rotY;
  if (o.rotZ) m.rotation.z = o.rotZ;
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}
export function cyl(
  three: typeof THREE,
  rTop: number,
  rBot: number,
  h: number,
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts & { rotX?: number; rotY?: number; rotZ?: number; seg?: number } = {},
) {
  const m = new three.Mesh(new three.CylinderGeometry(rTop, rBot, h, o.seg ?? 16), mat(three, color, o));
  m.position.set(...pos);
  if (o.rotX) m.rotation.x = o.rotX;
  if (o.rotY) m.rotation.y = o.rotY;
  if (o.rotZ) m.rotation.z = o.rotZ;
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}
export function ball(
  three: typeof THREE,
  r: number,
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts = {},
) {
  const m = new three.Mesh(new three.IcosahedronGeometry(r, o.flat ? 1 : 3), mat(three, color, o));
  m.position.set(...pos);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

export type BuildFn = (three: typeof THREE, group: THREE.Group) => ((t: number) => void) | void;

export interface StageProps {
  build: BuildFn;
  height?: number;
  background?: string;
  autoRotate?: boolean;
  distance?: number;
  targetY?: number;
}

export function Stage({
  build,
  height = 340,
  background = '#9ec7d8',
  autoRotate = true,
  distance = 8,
  targetY = 0.7,
}: StageProps) {
  const ref = useRef<HTMLDivElement>(null);
  const buildRef = useRef(build);
  buildRef.current = build;

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let w = el.clientWidth || 480;
    const h = height;

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(w, h);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    el.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(background);
    scene.fog = new THREE.Fog(new THREE.Color(background).getHex(), distance * 2.2, distance * 4.5);

    const camera = new THREE.PerspectiveCamera(34, w / h, 0.1, 200);
    const target = new THREE.Vector3(0, targetY, 0);

    scene.add(new THREE.HemisphereLight(0xdff0ff, 0x6b7a55, 0.62));
    const sun = new THREE.DirectionalLight(0xfff0d6, 1.15);
    sun.position.set(6, 11, 5);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    const s = 7;
    sun.shadow.camera.left = -s;
    sun.shadow.camera.right = s;
    sun.shadow.camera.top = s;
    sun.shadow.camera.bottom = -s;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 40;
    sun.shadow.bias = -0.0004;
    scene.add(sun);

    // textured grass ground
    const groundMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1 });
    groundMat.map = getTex(THREE, 'grass', 0x6f9e54, 24, 24);
    const ground = new THREE.Mesh(new THREE.CircleGeometry(distance * 1.6, 64), groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    const group = new THREE.Group();
    scene.add(group);
    const update = buildRef.current(THREE, group) || undefined;

    let az = Math.PI * 0.25;
    let el2 = Math.PI * 0.28;
    let dragging = false;
    let px = 0;
    let py = 0;
    const applyCam = () => {
      const r = distance;
      camera.position.set(
        target.x + r * Math.cos(el2) * Math.sin(az),
        target.y + r * Math.sin(el2),
        target.z + r * Math.cos(el2) * Math.cos(az),
      );
      camera.lookAt(target);
    };
    const dom = renderer.domElement;
    dom.style.cursor = 'grab';
    const down = (e: PointerEvent) => {
      dragging = true;
      px = e.clientX;
      py = e.clientY;
      dom.style.cursor = 'grabbing';
      dom.setPointerCapture(e.pointerId);
    };
    const move = (e: PointerEvent) => {
      if (!dragging) return;
      az -= (e.clientX - px) * 0.01;
      el2 = Math.max(0.08, Math.min(1.45, el2 + (e.clientY - py) * 0.01));
      px = e.clientX;
      py = e.clientY;
    };
    const up = (e: PointerEvent) => {
      dragging = false;
      dom.style.cursor = 'grab';
      try {
        dom.releasePointerCapture(e.pointerId);
      } catch {
        /* noop */
      }
    };
    dom.addEventListener('pointerdown', down);
    dom.addEventListener('pointermove', move);
    dom.addEventListener('pointerup', up);

    const clock = new THREE.Clock();
    let raf = 0;
    const loop = () => {
      const t = clock.getElapsedTime();
      if (autoRotate && !dragging) az += 0.0045;
      applyCam();
      if (update) update(t);
      renderer.render(scene, camera);
      raf = requestAnimationFrame(loop);
    };
    loop();

    const ro = new ResizeObserver(() => {
      w = el.clientWidth || w;
      renderer.setSize(w, h);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    });
    ro.observe(el);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      dom.removeEventListener('pointerdown', down);
      dom.removeEventListener('pointermove', move);
      dom.removeEventListener('pointerup', up);
      renderer.dispose();
      scene.traverse((obj) => {
        const anyObj = obj as unknown as {
          geometry?: THREE.BufferGeometry;
          material?: THREE.Material | THREE.Material[];
        };
        anyObj.geometry?.dispose?.();
        const m = anyObj.material;
        if (Array.isArray(m)) m.forEach((mm) => mm.dispose());
        else m?.dispose?.();
      });
      if (dom.parentNode === el) el.removeChild(dom);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return <div ref={ref} style={{ width: '100%', height, borderRadius: 12, overflow: 'hidden' }} />;
}

# Stage

Foundation for every 3D rig. Creates a three.js `WebGLRenderer`, an orbit camera (drag to rotate, auto-rotates when idle), hemisphere + directional sun light with soft shadows, and a grass ground disc. Exposes geometry helpers `box`, `cyl`, `ball`, `mat`.

```tsx
<Stage build={(THREE, group) => {
  group.add(box(THREE, [1,1,1], 0xdd6633, [0,0.5,0]));
  return (t) => { group.rotation.y = t; }; // optional per-frame update
}} />
```

import React from 'react';
import { Stage, box, ball } from './index';

const previews = {
  componentName: 'Stage',
  importPath: 'components/Stage',
  previews: [
    { name: 'Foundation', description: 'Reusable three.js viewport (orbit camera, sun + soft shadows, grass ground). Pass a build(THREE, group) callback.', render: () => (
      <Stage build={(t, g) => { g.add(box(t, [1, 1, 1], 0xdd6633, [0, 0.5, 0])); g.add(ball(t, 0.45, 0x4488cc, [1, 0.45, 0.6])); }} />
    ) },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, ball } from '../Stage';

// Shared peep builder — used by the Guest crowd and seated in rides. Supports
// varied skin tones, hair, shirt/trousers colours and facial EXPRESSIONS
// (happy / neutral / sad / surprised). Limbs pivot for a walk cycle or sit.
export type Expression = 'happy' | 'neutral' | 'sad' | 'surprised';
export interface PeepOpts {
  shirt?: number;
  trousers?: number;
  skin?: number;
  hair?: number;
  expression?: Expression;
  seated?: boolean;
}
export const SKIN_TONES = [0xf1c9a5, 0xe0a878, 0xc68642, 0x8d5524, 0x5c3a21];
export const SHIRTS = [0xc21a1a, 0x2f6fd0, 0x2e9e54, 0xe0a020, 0x8e44ad, 0xe06010, 0x18a0a0, 0xe060a0];
export const TROUSERS = [0x26305e, 0x3a2a1a, 0x333940, 0x5a3d22, 0x6a1030];
export const HAIRS = [0x4a3018, 0x1c1c1c, 0x7a5230, 0xb08040, 0x9a9a9a];

export function buildPeep(t: typeof THREE, o: PeepOpts = {}) {
  const SKIN = o.skin ?? 0xe0a878;
  const HAIR = o.hair ?? 0x4a3018;
  const SHIRT = o.shirt ?? 0xc21a1a;
  const TROU = o.trousers ?? 0x26305e;
  const SHOE = 0x2a1c10;
  const DARK = 0x1a1207;
  const expr = o.expression ?? 'happy';

  const grp = new t.Group();
  grp.add(box(t, [0.26, 0.14, 0.18], TROU, [0, 0.52, 0], { tex: 'fabric', repeat: [2, 1], rough: 0.9 }));
  grp.add(box(t, [0.3, 0.32, 0.2], SHIRT, [0, 0.74, 0], { tex: 'fabric', repeat: [2, 2], rough: 0.85 }));

  const head = new t.Group();
  head.position.set(0, 0.99, 0);
  head.add(ball(t, 0.12, SKIN, [0, 0, 0], { rough: 0.7 }));
  const hair = ball(t, 0.128, HAIR, [0, 0.04, -0.012], { rough: 0.9 });
  hair.scale.set(1.02, 0.72, 1.02);
  head.add(hair);

  const eyeR = expr === 'surprised' ? 0.032 : 0.026;
  [-0.045, 0.045].forEach((ex) => {
    head.add(ball(t, eyeR, 0xffffff, [ex, 0.02, 0.104], { rough: 0.4 }));
    head.add(ball(t, 0.013, 0x1b1b22, [ex, 0.02, 0.121], { rough: 0.3 }));
    const browTilt = expr === 'sad' ? (ex > 0 ? 0.35 : -0.35) : ex > 0 ? -0.15 : 0.15;
    head.add(box(t, [0.05, 0.012, 0.01], HAIR, [ex, expr === 'sad' ? 0.05 : 0.062, 0.108], { rotZ: browTilt }));
  });

  // mouth by expression
  if (expr === 'surprised') {
    head.add(ball(t, 0.028, DARK, [0, -0.04, 0.108], { rough: 0.5 }));
  } else if (expr === 'neutral') {
    head.add(box(t, [0.06, 0.012, 0.012], DARK, [0, -0.045, 0.11]));
  } else {
    const m = new t.Mesh(new t.TorusGeometry(0.035, 0.008, 8, 12, Math.PI), new t.MeshStandardMaterial({ color: DARK, roughness: 0.5 }));
    m.rotation.set(expr === 'sad' ? 0 : Math.PI, 0, 0);
    m.position.set(0, expr === 'sad' ? -0.06 : -0.035, 0.108);
    head.add(m);
  }
  head.add(ball(t, 0.018, SKIN, [0, -0.005, 0.12], { rough: 0.6 })); // nose
  grp.add(head);

  const limb = (px: number, py: number, col: number, len: number, hand?: number, texd?: boolean) => {
    const pivot = new t.Group();
    pivot.position.set(px, py, 0);
    pivot.add(box(t, [0.09, len, 0.11], col, [0, -len / 2, 0], texd ? { tex: 'fabric', repeat: [1, 2], rough: 0.85 } : { rough: 0.7 }));
    if (hand != null) pivot.add(ball(t, 0.05, hand, [0, -len, 0], { rough: 0.7 }));
    grp.add(pivot);
    return pivot;
  };
  const armL = limb(-0.19, 0.88, SHIRT, 0.32, SKIN, true);
  const armR = limb(0.19, 0.88, SHIRT, 0.32, SKIN, true);
  const legL = limb(-0.08, 0.46, TROU, 0.4, undefined, true);
  const legR = limb(0.08, 0.46, TROU, 0.4, undefined, true);
  legL.add(box(t, [0.12, 0.07, 0.2], SHOE, [0, -0.4, 0.03], { rough: 0.6 }));
  legR.add(box(t, [0.12, 0.07, 0.2], SHOE, [0, -0.4, 0.03], { rough: 0.6 }));

  if (o.seated) {
    legL.rotation.x = -1.5;
    legR.rotation.x = -1.5;
    armL.rotation.x = -1.1;
    armR.rotation.x = -1.1;
    if (expr === 'surprised') {
      armL.rotation.x = -2.6; // arms up!
      armR.rotation.x = -2.6;
    }
  }

  const walk = (time: number, phase = 0) => {
    const s = Math.sin(time * 5 + phase);
    legL.rotation.x = s * 0.5;
    legR.rotation.x = -s * 0.5;
    armL.rotation.x = -s * 0.45;
    armR.rotation.x = s * 0.45;
    grp.position.y = Math.abs(Math.cos(time * 5 + phase)) * 0.03;
  };
  return { group: grp, walk, head };
}

// A diverse crowd of walking guests — varied skin tones, outfits and moods.
export function Guest() {
  return (
    <Stage
      distance={5.2}
      targetY={0.6}
      autoRotate
      build={(t, g) => {
        const exprs: Expression[] = ['happy', 'neutral', 'surprised', 'happy', 'sad'];
        const peeps = exprs.map((expression, i) => {
          const p = buildPeep(t, {
            skin: SKIN_TONES[i % SKIN_TONES.length],
            hair: HAIRS[i % HAIRS.length],
            shirt: SHIRTS[i % SHIRTS.length],
            trousers: TROUSERS[i % TROUSERS.length],
            expression,
          });
          p.group.position.set((i - 2) * 0.85, 0, (i % 2) * 0.4 - 0.2);
          p.group.rotation.y = 0.3;
          g.add(p.group);
          return p;
        });
        return (time) => peeps.forEach((p, i) => p.walk(time, i * 1.3));
      }}
    />
  );
}

import React from 'react';
import { Guest } from './index';

const previews = {
  componentName: 'Guest',
  importPath: 'components/Guest',
  previews: [
    { name: '3D rig', description: "A park guest with an animated walk cycle, modelled from the RCT2 peep sprite. Drag to orbit.", render: () => <Guest /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// A wooden-coaster car, detailed from the RCT2 vehicle sprite: a rounded orange
// tub with a swept nose + tail coupler, chrome side trim, a headlight, two
// bogies of wheels, over-shoulder restraints, and two seated peeps (diverse
// skin + shirts, each with a face). Exported so WoodenCoaster builds a train.
export function buildCoasterCar(t: typeof THREE): THREE.Group {
  const g = new t.Group();
  const ORANGE = 0xe0601a;
  const ORANGE_D = 0xb5480f;
  const CHROME = 0xcfd4da;
  const DARK = 0x232327;
  const SEAT = 0x191a1e;

  // chassis + bogies
  g.add(box(t, [0.5, 0.1, 1.0], DARK, [0, 0.02, 0], { tex: 'metal', repeat: [3, 5], metal: 0.7, rough: 0.5 }));
  [-0.34, 0.34].forEach((z) => g.add(box(t, [0.56, 0.08, 0.24], DARK, [0, -0.04, z], { tex: 'metal', metal: 0.6, rough: 0.5 })));

  // tub: layered boxes for a rounded hull
  g.add(box(t, [0.58, 0.3, 1.0], ORANGE, [0, 0.24, 0], { tex: 'plastic', repeat: [2, 1], rough: 0.38 }));
  g.add(box(t, [0.64, 0.16, 0.94], ORANGE, [0, 0.2, 0], { tex: 'plastic', repeat: [2, 1], rough: 0.38 }));
  g.add(box(t, [0.5, 0.28, 0.86], SEAT, [0, 0.34, 0], { rough: 0.85 })); // interior well
  // chrome waist trim + number panel
  g.add(box(t, [0.66, 0.04, 0.96], CHROME, [0, 0.33, 0], { tex: 'metal', metal: 0.9, rough: 0.2 }));
  g.add(box(t, [0.52, 0.14, 0.02], 0xf5e6c8, [0, 0.24, 0.505], { rough: 0.5 })); // front panel
  // swept nose (front +z) + headlight
  g.add(box(t, [0.5, 0.26, 0.3], ORANGE_D, [0, 0.2, 0.56], { rotX: -0.7, tex: 'plastic', repeat: [1, 1], rough: 0.38 }));
  g.add(ball(t, 0.05, 0xfff3c0, [0, 0.24, 0.66], { emissive: 0xffcc55, rough: 0.3 }));
  // tail coupler
  g.add(cyl(t, 0.04, 0.04, 0.16, CHROME, [0, 0.18, -0.58], { rotX: Math.PI / 2, metal: 0.9, rough: 0.2, seg: 10 }));

  // two seated peeps front/back with restraints
  [0.2, -0.16].forEach((z, i) => {
    g.add(box(t, [0.46, 0.24, 0.05], SEAT, [0, 0.4, z - 0.2], { rough: 0.85 })); // seat back
    const p = buildPeep(t, { skin: SKIN_TONES[i], shirt: SHIRTS[(i * 3 + 2) % SHIRTS.length], seated: true, expression: i === 0 ? 'surprised' : 'happy' });
    p.group.scale.setScalar(0.52);
    p.group.position.set(0, 0.12, z);
    g.add(p.group);
    // over-shoulder restraint
    g.add(cyl(t, 0.02, 0.02, 0.34, DARK, [0, 0.62, z + 0.02], { rotZ: Math.PI / 2, metal: 0.5, rough: 0.4, seg: 8 }));
    [-0.12, 0.12].forEach((x) => g.add(cyl(t, 0.018, 0.018, 0.24, DARK, [x, 0.52, z + 0.06], { rotX: 0.5, metal: 0.5, rough: 0.4, seg: 8 })));
  });

  const wheel = (x: number, z: number) =>
    cyl(t, 0.1, 0.1, 0.07, 0x141417, [x, -0.05, z], { rotZ: Math.PI / 2, tex: 'metal', repeat: [4, 1], metal: 0.6, rough: 0.4, seg: 20 });
  [
    [-0.3, 0.34],
    [0.3, 0.34],
    [-0.3, -0.34],
    [0.3, -0.34],
  ].forEach(([x, z]) => g.add(wheel(x, z)));

  return g;
}

export function CoasterCar() {
  return (
    <Stage
      distance={4.2}
      targetY={0.45}
      build={(t, g) => {
        const TIE = 0x6b4626;
        for (let z = -1.4; z <= 1.4; z += 0.4) g.add(box(t, [0.98, 0.06, 0.12], TIE, [0, 0.02, z], { tex: 'wood', repeat: [3, 1], rough: 0.9 }));
        g.add(box(t, [0.07, 0.08, 3.0], 0x8b8f96, [-0.32, 0.09, 0], { tex: 'metal', repeat: [1, 20], metal: 0.85, rough: 0.3 }));
        g.add(box(t, [0.07, 0.08, 3.0], 0x8b8f96, [0.32, 0.09, 0], { tex: 'metal', repeat: [1, 20], metal: 0.85, rough: 0.3 }));
        const car = buildCoasterCar(t);
        car.position.y = 0.25;
        g.add(car);
        return (time) => {
          car.position.y = 0.25 + Math.sin(time * 2) * 0.015;
          car.rotation.z = Math.sin(time * 1.3) * 0.015;
        };
      }}
    />
  );
}

