import React from 'react';
import * as THREE from 'three';
import { Stage, box } from '../Stage';

// Animated water surface via a custom GLSL ShaderMaterial: summed sine waves
// displace the surface, with a depth colour gradient, view-dependent Fresnel
// rim, a moving sun specular highlight and glinting sparkles. Exported so the
// TerrainMap can flood its low ground with the same shader.
export function buildWater(t: typeof THREE, size = 4, seg = 96) {
  const geo = new t.PlaneGeometry(size, size, seg, seg);
  const mat = new t.ShaderMaterial({
    transparent: true,
    uniforms: {
      uTime: { value: 0 },
      uShallow: { value: new t.Color(0x6fd0e8) },
      uDeep: { value: new t.Color(0x123f78) },
      uSun: { value: new t.Vector3(6, 11, 5).normalize() },
    },
    vertexShader: `
      uniform float uTime;
      varying float vH;
      varying vec3 vWorld;
      void main() {
        vec3 p = position;
        float w = sin(p.x * 1.5 + uTime * 1.2) * 0.06
                + sin(p.y * 2.1 + uTime * 1.6) * 0.045
                + sin((p.x + p.y) * 0.9 - uTime * 1.3) * 0.05;
        p.z += w;
        vH = w;
        vec4 wp = modelMatrix * vec4(p, 1.0);
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      precision highp float;
      uniform float uTime;
      uniform vec3 uShallow;
      uniform vec3 uDeep;
      uniform vec3 uSun;
      varying float vH;
      varying vec3 vWorld;
      void main() {
        vec3 n = normalize(cross(dFdx(vWorld), dFdy(vWorld)));
        vec3 v = normalize(cameraPosition - vWorld);
        float fres = pow(1.0 - max(dot(n, v), 0.0), 3.0);
        vec3 base = mix(uDeep, uShallow, clamp(vH * 4.0 + 0.5, 0.0, 1.0));
        vec3 l = normalize(uSun);
        vec3 h = normalize(l + v);
        float spec = pow(max(dot(n, h), 0.0), 60.0);
        float diff = max(dot(n, l), 0.0) * 0.5 + 0.5;
        vec3 col = base * diff + vec3(1.0) * spec * 0.8 + fres * vec3(0.6, 0.8, 1.0) * 0.6;
        float sp = sin(vWorld.x * 40.0 + uTime * 8.0) * sin(vWorld.z * 40.0 - uTime * 6.0);
        col += smoothstep(0.985, 1.0, sp) * 0.5;
        gl_FragColor = vec4(col, 0.87);
      }
    `,
  });
  const mesh = new t.Mesh(geo, mat);
  mesh.rotation.x = -Math.PI / 2;
  return { mesh, update: (time: number) => (mat.uniforms.uTime.value = time) };
}

export function WaterTile() {
  return (
    <Stage
      distance={5}
      targetY={0.1}
      background="#bfe6f2"
      build={(t, g) => {
        // sandy basin so the water reads as a pool
        g.add(box(t, [4.2, 0.4, 4.2], 0xd9c48f, [0, -0.2, 0], { tex: 'sand', repeat: [4, 4], rough: 1 }));
        const water = buildWater(t, 4);
        water.mesh.position.y = 0.12;
        g.add(water.mesh);
        return (time) => water.update(time);
      }}
    />
  );
}

